<script setup lang="ts">
import { ref,watch,nextTick } from 'vue'
import type { Slide,Proposal,ProposalOperation } from '@/types/aippt'
const props=defineProps<{slide:Slide;disabled?:boolean;canApply:boolean;request:(instruction:string,history:{instruction:string;note?:string}[])=>Promise<Proposal>;apply:(proposal:Proposal,op:ProposalOperation,side:'before'|'after')=>Promise<void>}>();const instruction=ref(''),proposal=ref<Proposal|null>(null),busy=ref(false),error=ref(''),turns=ref<{instruction:string;note?:string;error?:string}[]>([]);let generation=0
watch(()=>props.slide.id,()=>{generation++;proposal.value=null;instruction.value='';error.value='';turns.value=[];busy.value=false})
async function propose(){const text=instruction.value.trim();if(!text||busy.value||props.disabled)return;const own=++generation,history=turns.value.slice(-5).map(({instruction,note})=>({instruction,...(note?{note}:{})}));turns.value.push({instruction:text});const turn=turns.value[turns.value.length-1];instruction.value='';proposal.value=null;busy.value=true;error.value='';try{const result=await props.request(text,history);if(own===generation){proposal.value=result;turn.note=`改了 ${result.operations.length} 处`}}catch(e:any){if(own===generation){error.value=e.message;turn.error=e.message}}finally{if(own===generation)busy.value=false}}
async function apply(op:ProposalOperation,side:'before'|'after'){const current=proposal.value,own=generation;if(!current)return;busy.value=true;try{await props.apply(current,op,side);await nextTick();if(own!==generation||proposal.value!==current)return;op.accepted=side==='after';current.revision=props.slide.revision;error.value=''}catch(e:any){if(own===generation&&proposal.value===current)error.value=e.message||'候选已过期，请重新生成'}finally{if(own===generation)busy.value=false}}
function protectedOp(op:ProposalOperation){return props.slide.blocks.some(b=>b.id===op.block_id&&b.locked)&&!op.accepted}
function show(v:unknown){return typeof v==='string'?v:JSON.stringify(v,null,2)}
</script>
<template><section><h4>AI 修改建议</h4><p>只生成建议副本，逐项采纳后保存。已手工修改的块受保护；固定页只替换内容。</p><ol v-if="turns.length" class="turns" aria-label="AI指令历史"><li v-for="(turn,i) in turns" :key="i"><p>{{turn.instruction}}</p><small v-if="turn.note">{{turn.note}}</small><p v-if="turn.error" role="alert">{{turn.error}}</p></li></ol><el-input v-model="instruction" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="例如：精简这页要点，保留数字和来源" :disabled="disabled||busy"/><el-button v-hasPermi="['aippt:ai:edit']" type="primary" :loading="busy" :disabled="disabled||!instruction.trim()" @click="propose">生成修改建议</el-button><el-alert v-if="error" type="error" :title="error"/><template v-if="proposal"><el-alert v-if="proposal.revision!==slide.revision" title="页面已变化，候选可能过期；重新生成后再采纳" type="warning" :closable="false"/><article v-for="(op,i) in proposal.operations" :key="op.op_id||op.id||i" class="operation"><strong>{{i+1}}. {{op.op}} · {{op.block_id}}</strong><p v-if="op.reason">{{op.reason}}</p><div class="comparison"><div><small>修改前</small><pre>{{show(op.before)}}</pre></div><div><small>建议内容</small><pre>{{show(op.after)}}</pre></div></div><el-tag v-if="protectedOp(op)" type="warning">手工内容受保护</el-tag><el-button v-else :disabled="disabled||!canApply||busy||!!op.accepted" type="primary" @click="apply(op,'after')">采纳此项</el-button><el-button :disabled="disabled||!canApply||busy||!op.accepted" @click="apply(op,'before')">撤回采纳</el-button></article><el-alert v-for="(d,i) in proposal.discarded||proposal.dropped||[]" :key="i" type="warning" :title="d.reason"/><el-alert v-for="(w,i) in proposal.warnings||[]" :key="'warning'+i" type="warning" :title="typeof w==='string'?w:w.message"/><el-button @click="proposal=null">舍弃建议</el-button></template></section></template>
<style scoped>p{font-size:13px;line-height:1.6;color:#606266}.el-button{margin-top:12px}.operation{padding:14px 0;border-bottom:1px solid #ebeef5}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:10px}.comparison pre{font-size:12px;white-space:pre-wrap;word-break:break-word;max-height:260px;overflow:auto;background:#f5f7fa;padding:8px}</style>
